using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator renamed from "Discriminator" to "$type".
            // Preserve the EF8 property name so existing 500K documents remain readable
            // and direct SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|Key" to just "Key".
            // Map an explicit string property to the JSON "id" so EF9 can read
            // existing documents whose id is "Product|123".
            entity.Property(p => p.CosmosId)
                  .ToJsonProperty("id")
                  .HasValueGenerator<Ef8CosmosIdGenerator>();
            entity.HasKey(p => p.CosmosId);

            // BREAKING CHANGE 3 — HasIndex() now throws for Cosmos provider.
            // Removed the HasIndex(p => p.Sku) call; Cosmos manages indexes itself.
        });
    }
}

/// <summary>
/// Reproduces the EF8 "Product|{key}" id format for new inserts.
/// </summary>
class Ef8CosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"Product|{Guid.NewGuid().ToString("N")[..8]}";
}

class Product
{
    public string CosmosId { get; set; } = null!; // JSON "id" — e.g. "Product|123"
    public int Id { get; set; }
    public string Sku { get; set; } = null!;
}

